import pandas as pd

# Read the CSV file
file_path = '/tmp/data/task_mqom6e0a/dataset/TA/tables/english_table/ESSER_III_Learning_Loss_Program_Codes/PRC 181 Learning Loss.csv'
df = pd.read_csv(file_path, header=None)

# Print header rows to identify intervention columns
print("HEADER STRUCTURE - Intervention Columns:")
print("=" * 80)
for i in range(30, 80):
    row_data = df.iloc[i]
    if 'Summer learning' in str(row_data[0]) or 'Afterschool programs' in str(row_data[0]) or 'Extended instructional' in str(row_data[0]) or 'Tutoring' in str(row_data[0]) or 'Additional classroom' in str(row_data[0]):
        print(f"Row {i}: {row_data[0]}")

# Find Alamance/Burlington and Alexander County data rows
print("\n" + "=" * 80)
print("ALAMANCE/BURLINGTON DATA:")
for i, row in df.iterrows():
    if str(row[0]) == '010':
        print(f"Row {i} - Alamance/Burlington")
        for j in range(10, 27):
            val = row[j] if j < len(row) else 'N/A'
            try:
                num_val = float(val) if val not in ['N/A', '', 'nan'] else 0
                if num_val > 0:
                    print(f"  Column {j}: ${num_val:,.2f}")
                else:
                    print(f"  Column {j}: {val}")
            except:
                print(f"  Column {j}: {val}")
        break

print("\n" + "=" * 80)
print("ALEXANDER COUNTY DATA:")
for i, row in df.iterrows():
    if str(row[0]) == '020':
        print(f"Row {i} - Alexander County")
        for j in range(10, 27):
            val = row[j] if j < len(row) else 'N/A'
